const RetentionFeature={id:"retention",name:"Retention",icon:"handshake",route:!1,TYPES:{satisfaction_check:["Satisfaction check","sentiment_satisfied"],review_request:["Review request","star"],referral:["Referral","group_add"],warranty:["Warranty","verified_user"],service:["Service reminder","build"],repeat_opportunity:["Repeat opportunity","repeat"]},render(e={}){return this.renderCustomer(Number(e.customerId),e)},meta(e){const t=this.TYPES[e]||["Retention action","handshake"];return{label:t[0],icon:t[1]}},async renderCustomer(e,t={}){if(!Number.isInteger(e)||e<=0)return'<div class="empty-state"><span class="material-symbols-rounded">person_off</span><div>Choose a customer first</div></div>';let a=null,n=[],s={};try{a=await DB.getCustomer(e)}catch(e){}try{n=await DB.getRetentionRecords({customerId:e})}catch(e){console.error("Retention load failed:",e)}try{s=await DB.getContactPreferences(e)||{}}catch(e){}const o=a?.fullName||[a?.firstName,a?.lastName].filter(Boolean).join(" ")||"Customer",r=n.filter(e=>!["completed","cancelled"].includes(e.status)),i=e=>Array.isArray(s)?s.find(t=>t.channel===e)?.status:s[e]?.status||s[e]||"unknown";return`<div class="fade-in">\n      ${App.renderTopHeader({title:"Aftercare",showBack:!0,backHref:t.jobId?`jobs?id=${t.jobId}`:`customer?id=${e}`,actions:`<button class="btn btn-primary btn-sm" data-action="RetentionFeature.openAdd" data-args='${JSON.stringify([e,Number(t.orderId)||null,Number(t.jobId)||null])}'><span class="material-symbols-rounded">add</span>Action</button>`})}\n      <div class="p-md">\n        <div class="card card-page"><strong>${Utils.escapeHtml(o)}</strong><div class="fs-13 text-secondary mt-6">${r.length} open aftercare action${1===r.length?"":"s"}</div></div>\n        <div class="card card-page"><div class="section-label">Contact preferences</div><div class="grid-2 gap-sm">\n          ${this.preferenceButton(e,"phone","Phone",i("phone"))}\n          ${this.preferenceButton(e,"email","Email",i("email"))}\n          ${this.preferenceButton(e,"sms","SMS",i("sms"))}\n          ${this.preferenceButton(e,"whatsapp","WhatsApp",i("whatsapp"))}\n        </div><div class="hint mt-sm">Preferences are explicit. Opening a messaging app never counts as consent or delivery.</div></div>\n        <div class="section-label">Aftercare timeline</div>\n        ${n.length?n.sort((e,t)=>new Date(e.dueAt||e.createdAt)-new Date(t.dueAt||t.createdAt)).map(e=>this.renderRecord(e)).join(""):'<div class="empty-state"><span class="material-symbols-rounded">handshake</span><div>No aftercare actions yet</div></div>'}\n      </div>\n    </div>`},preferenceButton(e,t,a,n){const s="opted_in"===n;return`<button class="btn ${s?"btn-primary":"btn-outline"} btn-sm" aria-pressed="${s}" data-action="RetentionFeature.togglePreference" data-args='${JSON.stringify([e,t,s?"opted_out":"opted_in"])}'>${Utils.escapeHtml(a)} · ${Utils.escapeHtml(String(n||"unknown").replace("_"," "))}</button>`},renderRecord(e){const t=this.meta(e.type),a="completed"===e.status;return`<div class="card card-page"><div class="flex items-start gap-sm"><span class="material-symbols-rounded">${t.icon}</span><div class="flex-1"><div class="flex justify-between gap-sm"><strong>${Utils.escapeHtml(t.label)}</strong><span class="badge">${Utils.escapeHtml(e.status||"planned")}</span></div><div class="fs-12 text-tertiary mt-2">${e.dueAt?`Due ${Utils.formatDate(e.dueAt,"short")}`:"No due date"}${e.notes?` · ${Utils.escapeHtml(e.notes)}`:""}</div>${e.score?`<div class="fs-13 mt-6">Satisfaction ${e.score}/5</div>`:""}${e.outcome?`<div class="fs-13 mt-6">${Utils.escapeHtml(e.outcome)}</div>`:""}</div></div>${a?"":`<button class="btn btn-outline btn-sm btn-block mt-sm" data-action="RetentionFeature.openComplete" data-args='${JSON.stringify([e.id,e.customerId,e.type])}'><span class="material-symbols-rounded">done</span>Complete</button>`}</div>`},openAdd(e,t=null,a=null){const n=new Date(Date.now()+6048e5).toISOString().slice(0,10);App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>New aftercare action</h3><button class="btn btn-ghost btn-sm" data-action="App.closeModal" aria-label="Close"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body">\n      <div class="form-group"><label for="retention-type">Action</label><select class="input" id="retention-type">${Object.entries(this.TYPES).map(([e,t])=>`<option value="${e}">${t[0]}</option>`).join("")}</select></div>\n      <div class="form-group"><label for="retention-due">Due date</label><input class="input" id="retention-due" type="date" value="${n}" required></div>\n      <div class="form-group"><label for="retention-notes">Notes</label><textarea class="input" id="retention-notes" rows="3" placeholder="Facts or context only"></textarea></div>\n      <button class="btn btn-primary btn-block" data-action="RetentionFeature.saveNew" data-args='${JSON.stringify([e,t,a])}'>Save action</button>\n    </div>`)},async saveNew(e,t=null,a=null){const n=document.getElementById("retention-type")?.value,s=document.getElementById("retention-due")?.value,o=(document.getElementById("retention-notes")?.value||"").trim();if(!this.TYPES[n]||!s)return Toast.show("Choose an action and due date","warning");try{await DB.addRetentionRecord({customerId:e,type:n,dueAt:s,notes:o,status:"planned",...Number(t)?{orderId:Number(t)}:{},...Number(a)?{jobId:Number(a)}:{}}),App.closeModal(),Toast.show("Aftercare action saved","success"),App.navigate("retention",{customerId:e})}catch(e){console.error("Retention save failed:",e),Toast.show("Could not save aftercare action","error")}},openComplete(e,t,a){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Complete aftercare</h3><button class="btn btn-ghost btn-sm" data-action="App.closeModal" aria-label="Close"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body">${"satisfaction_check"===a?'<div class="form-group"><label for="retention-score">Satisfaction</label><select class="input" id="retention-score"><option value="">Choose score</option><option value="1">1 — very unhappy</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5">5 — very happy</option></select></div>':""}<div class="form-group"><label for="retention-outcome">Outcome</label><textarea class="input" id="retention-outcome" rows="3" placeholder="What happened?"></textarea></div><button class="btn btn-primary btn-block" data-action="RetentionFeature.saveCompletion" data-args='${JSON.stringify([e,t,a])}'>Complete action</button></div>`)},async saveCompletion(e,t,a){const n=Number(document.getElementById("retention-score")?.value||0),s=(document.getElementById("retention-outcome")?.value||"").trim();if("satisfaction_check"===a&&!(n>=1&&n<=5))return Toast.show("Choose a satisfaction score","warning");try{await DB.updateRetentionRecord(e,{status:"completed",completedAt:(new Date).toISOString(),...n?{score:n}:{},...s?{outcome:s}:{}}),App.closeModal(),Toast.show("Aftercare action completed","success"),App.navigate("retention",{customerId:t})}catch(e){console.error("Retention completion failed:",e),Toast.show("Could not complete action","error")}},async togglePreference(e,t,a){try{await DB.setContactPreference({customerId:e,channel:t,status:a,effectiveAt:(new Date).toISOString(),consentSource:"advisor_recorded"},`contact-preference:${e}:${t}:${Date.now()}`),Toast.show(`${t} ${a.replace("_"," ")}`,"success"),App.navigate("retention",{customerId:e})}catch(e){console.error("Preference update failed:",e),Toast.show("Could not update preference","error")}}};App.registerFeature(RetentionFeature);
